import{_ as t,d as a,e as o,y as i}from"./chunks/framework.D7CAgLCq.js";const f=JSON.parse('{"title":"Two effective links can still fail as a whole","description":"Separate edge averages, joint response, representation, and shared resources.","frontmatter":{"title":"Two effective links can still fail as a whole","description":"Separate edge averages, joint response, representation, and shared resources."},"headers":[],"relativePath":"en/concepts/chain.md","filePath":"en/concepts/chain.md"}'),n={name:"en/concepts/chain.md"};function s(r,e,c,l,h,d){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="two-effective-links-can-still-fail-as-a-whole" tabindex="-1">Two effective links can still fail as a whole <a class="header-anchor" href="#two-effective-links-can-still-fail-as-a-whole" aria-label="Permalink to &quot;Two effective links can still fail as a whole&quot;">​</a></h1><p>An intervention changes an intermediate variable. Changing that variable also affects an outcome. It is tempting to multiply those two average effects. The missing question is whether <strong>the same units respond along both links under compatible conditions</strong>.</p><h2 id="the-book-s-finite-counterexample" tabindex="-1">The book’s finite counterexample <a class="header-anchor" href="#the-book-s-finite-counterexample" aria-label="Permalink to &quot;The book’s finite counterexample&quot;">​</a></h2><p>Let two equally weighted types be s = 0 and s = 1. Set the mediator to m(a) = a(1 − s) and the outcome to y(a,m) = sm. In type 0, treatment changes the mediator but the outcome does not respond to it. In type 1, the outcome responds to the mediator, but treatment does not change the mediator.</p><p>The treatment-to-mediator average effect is 1/2. The mediator-to-outcome average effect is also 1/2. Yet the treatment’s effect through the whole chain is zero for both types. Multiplying the averages gives 1/4 and loses the response correspondence.</p><p>This is a mathematical counterexample under specified functions, not a measured population effect. It rejects unconditional multiplication. It does not cancel a total effect independently identified by a suitable study, nor require every total-effect study to identify every microscopic mechanism.</p><h2 id="three-different-composition-questions" tabindex="-1">Three different composition questions <a class="header-anchor" href="#three-different-composition-questions" aria-label="Permalink to &quot;Three different composition questions&quot;">​</a></h2><div class="xk-table"><table><thead><tr><th>Question</th><th>What must be checked</th></tr></thead><tbody><tr><td>Do successive representations preserve the same final answer?</td><td>The distinctions needed for that final query, across the actual reachable representations.</td></tr><tr><td>Do causal links support the effect of the chain as a whole?</td><td>Same-case correspondence, joint responses, common support, timing, capacity, and the endpoint.</td></tr><tr><td>Can individually feasible tasks be executed together?</td><td>Shared resources, locations, deadlines, and valid permissions.</td></tr></tbody></table></div><p>The <a href="./../cases/mars-climate-orbiter.html">Mars Climate Orbiter case</a> concerns a documented unit-interface failure. It is not an empirical instance of the two-type causal counterexample: NASA’s report did not estimate the two average effects above.</p><p>A person can really acquire skills while the local labor market offers no relevant job. Preserving the learning result helps identify the missing employment connection; neither the successful first step nor the unsuccessful endpoint should erase the other.</p><p>Read <a href="/xi-kari-skill/handbook/en/theory/part-02.html#section-2-4-2">§2.4.2</a>, <a href="/xi-kari-skill/handbook/en/theory/appendix-c.html#section-c-12">C.12</a>, and <a href="./joint-feasibility.html">joint feasibility</a>.</p>',11)])])}const m=t(n,[["render",s]]);export{f as __pageData,m as default};
